"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

/* ===== Health Display ===== */
interface HealthProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  max?: number;
}

const Health = React.forwardRef<HTMLDivElement, HealthProps>(
  ({ className, value, max = 100, ...props }, ref) => {
    const isLow = value <= 25;
    const glowClass = isLow ? "cs-hud-glow-red" : "cs-hud-glow";

    return (
      <div
        ref={ref}
        className={cn("flex items-center gap-2", className)}
        {...props}
      >
        <span className={cn("text-2xl", glowClass)}>+</span>
        <span className={cn("cs-font-hud text-3xl tabular-nums", glowClass)}>
          {value}
        </span>
      </div>
    );
  }
);
Health.displayName = "Health";

/* ===== Armor Display ===== */
interface ArmorProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  hasHelmet?: boolean;
}

const Armor = React.forwardRef<HTMLDivElement, ArmorProps>(
  ({ className, value, hasHelmet = false, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn("flex items-center gap-2", className)}
        {...props}
      >
        <span className="cs-hud-glow text-2xl">
          {hasHelmet ? "⛑" : "🛡"}
        </span>
        <span className="cs-font-hud text-3xl tabular-nums cs-hud-glow">
          {value}
        </span>
      </div>
    );
  }
);
Armor.displayName = "Armor";

/* ===== Ammo Display ===== */
interface AmmoProps extends React.HTMLAttributes<HTMLDivElement> {
  current: number;
  reserve: number;
  weapon?: string;
}

const Ammo = React.forwardRef<HTMLDivElement, AmmoProps>(
  ({ className, current, reserve, weapon, ...props }, ref) => {
    const isLow = current <= 5;
    const glowClass = isLow ? "cs-hud-glow-red" : "cs-hud-glow";

    return (
      <div
        ref={ref}
        className={cn("flex items-center gap-1", className)}
        {...props}
      >
        {weapon && (
          <span className="cs-font-ui text-xs text-[var(--cs-hud-amber)] mr-2 opacity-70">
            {weapon}
          </span>
        )}
        <span className={cn("cs-font-hud text-3xl tabular-nums", glowClass)}>
          {current}
        </span>
        <span className="cs-hud-glow text-lg mx-0.5">/</span>
        <span className="cs-font-hud text-xl tabular-nums cs-hud-glow opacity-80">
          {reserve}
        </span>
      </div>
    );
  }
);
Ammo.displayName = "Ammo";

/* ===== Money Display ===== */
interface MoneyProps extends React.HTMLAttributes<HTMLDivElement> {
  amount: number;
}

const Money = React.forwardRef<HTMLDivElement, MoneyProps>(
  ({ className, amount, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn("flex items-center", className)}
        {...props}
      >
        <span className="cs-font-hud text-xl tabular-nums cs-hud-glow-green">
          ${amount.toLocaleString()}
        </span>
      </div>
    );
  }
);
Money.displayName = "Money";

/* ===== Timer Display ===== */
interface TimerProps extends React.HTMLAttributes<HTMLDivElement> {
  time: string;
  isLow?: boolean;
}

const Timer = React.forwardRef<HTMLDivElement, TimerProps>(
  ({ className, time, isLow = false, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn("flex items-center justify-center", className)}
        {...props}
      >
        <span
          className={cn(
            "cs-font-hud text-2xl tabular-nums",
            isLow ? "cs-hud-glow-red" : "cs-hud-glow"
          )}
        >
          {time}
        </span>
      </div>
    );
  }
);
Timer.displayName = "Timer";

/* ===== Full HUD Layout ===== */
interface HudProps extends React.HTMLAttributes<HTMLDivElement> {
  health: number;
  armor: number;
  hasHelmet?: boolean;
  ammoCurrent: number;
  ammoReserve: number;
  weapon?: string;
  money: number;
  time?: string;
  timerLow?: boolean;
}

const Hud = React.forwardRef<HTMLDivElement, HudProps>(
  (
    {
      className,
      health,
      armor,
      hasHelmet = false,
      ammoCurrent,
      ammoReserve,
      weapon,
      money,
      time = "1:45",
      timerLow = false,
      ...props
    },
    ref
  ) => {
    return (
      <div
        ref={ref}
        className={cn(
          "relative w-full bg-black/70 p-4 backdrop-blur-sm",
          className
        )}
        {...props}
      >
        {/* Top row: Money + Timer */}
        <div className="flex items-center justify-between mb-4">
          <Money amount={money} />
          <Timer time={time} isLow={timerLow} />
        </div>

        {/* Bottom row: Health/Armor + Ammo */}
        <div className="flex items-end justify-between">
          <div className="flex items-center gap-6">
            <Health value={health} />
            <Armor value={armor} hasHelmet={hasHelmet} />
          </div>
          <Ammo current={ammoCurrent} reserve={ammoReserve} weapon={weapon} />
        </div>
      </div>
    );
  }
);
Hud.displayName = "Hud";

export {
  Health,
  Armor,
  Ammo,
  Money,
  Timer,
  Hud,
  type HealthProps,
  type ArmorProps,
  type AmmoProps,
  type MoneyProps,
  type TimerProps,
  type HudProps,
};

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
